clear allclose all%N  = 200;M  = 5000;tmax = 10;Tmax = tmax/4;t    =  linspace(0,tmax,M);T    =  linspace(0,Tmax,N+1);T(1) = []; %remove first time instant to avoid divition over 0stdT = Tmax/30;muT = Tmax/4;rho = 0.02;S = exp(-abs(((T-muT)/stdT).^2));S = S(:);[K] = simrelax(T,t,'T2');y = K*S;SNR = 100;y = y + (max(y)/SNR)*randn(size(y));figure(1);subplot(121),plot(T,S,'b')xlabel('Relaxation time')subplot(122),plot(t,y,'b')%% Reconstruction I=eye(length(S));D=-eye(length(S)-1);D=[D zeros(length(D),1)];D=[zeros(length(D),1)'; D];D=D+I;% T0 BE COMPLETED params.y = y;params.K = K;params.D = D;params.mu = 0.01;params.lambda = 0.00015;params.n = length(S);params.beta = 10^-3;%[f_lambda, g,Hessian,J] = func(x,params);%%%%%%% enter all parameters and options %%%%%%%%%%%%%%%%%%%%%%%%%params.TolX=10^-3;params.TolF=10^-3;params.MaxIter=10^3;params.TolG=10^-3;params.kmax=10000;options.alpha=1;options.method='Newton'; %%Newton , Quasi-Newton, gradient, Fletcher, Gauss-Newton, Levenbergoptions.step = 'variable';options.const=10^-3;options.beta=0.75;S0=ones(length(S),1);condition=0;flag = 1;tol = 10^-3;Sh_pre = S0;% %% Exterior penality method% % while(condition==0)% [Sh,result,xval]= optimdescent('func2',params,options,S0);% Sb=Sh;% critb=result.crit;% params.mu = params.mu*2;% [Sh,result,xval]= optimdescent('func2',params,options,S0);% if(norm(Sh-Sb)/norm(Sb)<=10^-3)%     condition=1;% end% end%% Log barrier Methodoptions.step = 'logbarrier';while flag[Sh]=optimdescent('fghlog',params,options,S0);if norm(Sh - Sh_pre)<tolflag=0;endSh_pre=Sh;params.mu=params.mu/2;end% params.mu=0.1;% [Sh]=optimdescent('fghlog',params,options,S0);figure (2)subplot (121)plot(T, S, 'r')title('Original S')subplot (122)plot(T, Sh, 'b')title('Estimated S')